import csv
from collections import defaultdict
zones={
 "Core_mid":"95a195d5-d0ce-5098-bcec-ca1a2e9c4f28",
 "Perimeter_mid_ZN_3":"49eac0ff-63d2-57a8-90a0-fdee8aaf25a6",
 "Perimeter_top_ZN_3":"66009ccf-dd88-5be4-87fd-ed38ec990e48",
}
ids=set(zones.values())
date="2018-10-04"
sums=defaultdict(float); counts=defaultdict(int)
with open(VALUES_CSV) as f:
    rd=csv.DictReader(f)
    for r in rd:
        if r["timeseries_id"] in ids and r["timestamp"].startswith(date):
            v=r["value"]
            if v not in ("", None):
                sums[r["timeseries_id"]]+=float(v)
                counts[r["timeseries_id"]]+=1
for name,tid in zones.items():
    print(name, "n=",counts[tid], "sum(W*h)=",sums[tid], "kWh=",sums[tid]/1000)
